#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

ROOT="$(cd "$(dirname "$0")/.." && pwd)"

# This project is done in Edge: pages open there, where the Google account is signed in.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  open -a "Microsoft Edge" "$url" >/dev/null 2>&1 || open "$url" >/dev/null 2>&1 || warn "kon geen browser openen, ga er zelf heen: $url"
}

# The key file Google just downloaded: the newest .json in Downloads that is a service account key.
newest_key_file() {
  local file
  while IFS= read -r file; do
    if grep -q '"type": *"service_account"' "$file" 2>/dev/null; then printf '%s' "$file"; return 0; fi
  done < <(ls -t "$HOME"/Downloads/*.json 2>/dev/null)
  return 1
}

# One field of the key file, read with Node so the file is never printed.
key_field() { node -e 'const key = JSON.parse(require("fs").readFileSync(process.argv[1], "utf8")); process.stdout.write(String(key[process.argv[2]] ?? ""))' "$1" "$2"; }

run_wizard() {

TOTAL_STAGES=6
ENV_FILE="$ROOT/.env.local"

banner "Search Console koppelen aan Parkje weg"
say "Je maakt een robotgebruiker aan die alleen mag meelezen in Search Console."
say "Daarmee haalt de site elke dag zelf de zoekcijfers op."
printf '\n'
pause "Druk op Enter om te beginnen."

stage "Search Console API aanzetten"
PROJECT_QUERY=""
GOOGLE_CLOUD_PROJECT=$(_existing GOOGLE_CLOUD_PROJECT || true)
[[ -n "$GOOGLE_CLOUD_PROJECT" ]] && PROJECT_QUERY="?project=$GOOGLE_CLOUD_PROJECT"
say "Dit gebeurt in het Google Cloud-project dat je al hebt voor de Google-scores."
open_url "https://console.cloud.google.com/apis/library/searchconsole.googleapis.com${PROJECT_QUERY}"
step "Controleer bovenin dat het juiste project geselecteerd is."
step "De titel is 'Google Search Console API'. Klik op 'Enable' (NL: 'Inschakelen')."
note "Dit is gratis en heeft geen betaalaccount nodig."
pause "Ingeschakeld? Druk op Enter."

stage "Robotgebruiker aanmaken"
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts/create${PROJECT_QUERY}"
step "Naam: parkjeweg-search-console. Klik op 'Create and continue' (NL: 'Maken en doorgaan')."
step "Bij rollen en toegang vul je NIETS in: klik op 'Continue' en dan op 'Done' (NL: 'Klaar')."
note "Zonder rollen kan deze gebruiker niets in je Google Cloud-project. Hij krijgt alleen leesrecht in Search Console."
pause "Aangemaakt? Druk op Enter."

stage "Sleutelbestand downloaden"
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts${PROJECT_QUERY}"
step "Klik op het e-mailadres van 'parkjeweg-search-console'."
step "Tabblad 'Keys' (NL: 'Sleutels') > 'Add key' > 'Create new key' (NL: 'Nieuwe sleutel maken')."
step "Kies 'JSON' en klik op 'Create'. Er wordt een .json-bestand gedownload."
note "Meldt Google dat sleutels maken is uitgeschakeld? Stop dan hier en zeg het tegen Claude."
pause "Gedownload? Druk op Enter."
KEY_FILE=$(newest_key_file || true)
if [[ -n "$KEY_FILE" ]]; then
  note "Gevonden: $KEY_FILE"
  confirm "Is dit het bestand dat je net downloadde?" || KEY_FILE=""
fi
while [[ -z "$KEY_FILE" || ! -f "$KEY_FILE" ]]; do
  ask KEY_FILE "Sleep het .json-bestand hierheen en druk op Enter:" || { warn "Geen bestand opgegeven."; exit 1; }
  KEY_FILE="${KEY_FILE//\\ / }"; KEY_FILE="${KEY_FILE%\'}"; KEY_FILE="${KEY_FILE#\'}"
  [[ -f "$KEY_FILE" ]] || warn "Dat bestand bestaat niet: probeer het opnieuw."
done
ROBOT_EMAIL=$(key_field "$KEY_FILE" client_email)
if [[ -z "$ROBOT_EMAIL" || -z "$(key_field "$KEY_FILE" private_key)" ]]; then
  warn "Dit is geen sleutelbestand van een robotgebruiker. Start het script opnieuw."
  exit 1
fi
printf '  %s✓ sleutelbestand gelezen%s\n' "$GREEN" "$RESET"

stage "Robotgebruiker leesrecht geven in Search Console"
say "Voeg dit e-mailadres toe als gebruiker van parkjeweg.nl:"
printf '\n    %s%s%s\n\n' "$BOLD" "$ROBOT_EMAIL" "$RESET"
printf '%s' "$ROBOT_EMAIL" | pbcopy 2>/dev/null && note "Het adres staat op je klembord: plakken met Cmd+V."
open_url "https://search.google.com/search-console/users?resource_id=sc-domain%3Aparkjeweg.nl"
step "Klik op 'Add user' (NL: 'Gebruiker toevoegen')."
step "Plak het e-mailadres. Kies bij rechten 'Restricted' (NL: 'Beperkt'): dat is alleen lezen."
step "Klik op 'Add' (NL: 'Toevoegen')."
pause "Toegevoegd? Druk op Enter."

stage "Sleutel bewaren en testen"
say "De sleutel komt in .env.local op deze Mac, nergens anders op het scherm."
write_env GSC_SERVICE_ACCOUNT "$(base64 < "$KEY_FILE" | tr -d '\n')"
CHECK=""
until CHECK=$(cd "$ROOT" && node --env-file=.env.local scripts/check-search-console.mjs 2>&1); do
  warn "Het lukt nog niet: $CHECK"
  note "Net toegevoegde rechten hebben soms een minuut nodig."
  confirm "Opnieuw proberen?" || break
done
if [[ "$CHECK" == ok:* ]]; then
  printf '  %s✓ Search Console antwoordt%s %s\n' "$GREEN" "$RESET" "${CHECK#ok: }"
else
  SKIPPED+=("De test is niet gelukt: draai later 'node --env-file=.env.local scripts/check-search-console.mjs'")
fi
pause "Druk op Enter."

stage "Sleutel naar de prijsrondes en opruimen"
say "De prijsrondes draaien bij GitHub. Daar hebben ze dezelfde sleutel nodig, als geheim."
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  (cd "$ROOT" && set_secret GSC_SERVICE_ACCOUNT "$GSC_SERVICE_ACCOUNT")
elif confirm "Geheim nu zelf bij GitHub plakken?"; then
  printf '%s' "$GSC_SERVICE_ACCOUNT" | pbcopy
  note "De sleutel staat op je klembord, niet op het scherm."
  open_url "https://github.com/frontero/weekend-deals/settings/secrets/actions/new"
  step "Name: GSC_SERVICE_ACCOUNT"
  step "Secret: klik in het veld en plak met Cmd+V."
  step "Klik op 'Add secret'."
  pause "Toegevoegd? Druk op Enter. Daarna maak ik je klembord leeg."
  printf '' | pbcopy
  printf '  %s✓ klembord leeggemaakt%s\n' "$GREEN" "$RESET"
else
  SKIPPED+=("GitHub-geheim GSC_SERVICE_ACCOUNT niet gezet: de rondes halen dan nog geen zoekcijfers op")
fi
say "Het gedownloade bestand is nu niet meer nodig. Laat het niet in Downloads staan."
if confirm "Bestand naar de prullenbak verplaatsen?"; then
  mv "$KEY_FILE" "$HOME/.Trash/" && printf '  %s✓ verplaatst naar de prullenbak%s\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Verwijder zelf het sleutelbestand: $KEY_FILE")
fi

finish
say "Zeg tegen Claude dat het gelukt is. Dan worden de zoekcijfers gekoppeld aan /beheer/seo."
printf '\n'
}

run_wizard "$@"; exit
